import os

def write_deck_file(deck_name, cards_dict):
    path = f"tools/decks/{deck_name}.py"
    with open(path, "w", encoding="utf-8") as f:
        f.write(f"# Mazzo: {deck_name}\n")
        f.write("# 120 carte uniche calibrate pedagogicamente da A1 a C2 (20 carte per livello)\n\n")
        f.write("CARDS = {\n")
        for lvl in ["a1", "a2", "b1", "b2", "c1", "c2"]:
            f.write(f'    "{lvl}": [\n')
            for card in cards_dict[lvl]:
                titolo, incipit, proibite, usare = card
                f.write("        (\n")
                f.write(f'            {repr(titolo)},\n')
                f.write(f'            {repr(incipit)},\n')
                f.write(f'            {repr(proibite)},\n')
                f.write(f'            {repr(usare)}\n')
                f.write("        ),\n")
            f.write("    ],\n")
        f.write("}\n")
    print(f"Written {path}")

